/* =============================================================
   OVARIAN CANCER PRESENTATION  (AJ-OVC-2026)
   -------------------------------------------------------------
   1. Slide background images
   2. Supporting medical images
   3. Slide navigation (keyboard, swipe)
   The two built-in pictures (slides 2 and 3) are stored at the
   very bottom of this file. You never need to edit that part.
   ============================================================= */

document.addEventListener("DOMContentLoaded", () => {
    const presentation = document.querySelector("#presentation");
    const slides = Array.from(document.querySelectorAll(".slide"));

    let currentSlide = 0;
    let touchStartX = 0;

    // ==========================================
    // 1. BACKGROUND IMAGES  (images/backgrounds/)
    // ==========================================

    const backgrounds = {
        "01": "bg-01-title.png",
        "02": "bg-02-group-members.jpeg",
        "03": "bg-03-ovarian-cancer.png",
        "04": "bg-04-cancer-types.png",
        "05": "bg-05-risk-factors.png",
        "06": "bg-06-disease-development.png",
        "07": "bg-07-symptoms.jpeg",
        "08": "bg-08-symptom-progression.jpeg",
        "09": "bg-09-stages-overview.png",
        "10": "bg-10-stage-one.jpeg",
        "11": "bg-11-stage-two.jpeg",
        "12": "bg-12-stage-three.jpeg",
        "13": "bg-13-stage-four.jpeg",
        "14": "bg-14-disease-progression.png",
        "15": "bg-15-complications-one.jpeg",
        "16": "bg-16-complications-two.jpeg",
        "17": "bg-17-diagnosis.jpeg",
        "18": "bg-18-examination-imaging.jpeg",
        "19": "bg-19-markers-tissue.jpeg",
        "20": "bg-20-brca-genetics.png",
        "21": "bg-21-genetic-syndromes.jpeg",
        "22": "bg-22-mutations.jpeg",
        "23": "bg-23-treatment.jpeg",
        "24": "bg-24-targeted-therapy.png",
        "25": "bg-25-conclusion.jpeg",
        "26": "bg-26-references.jpeg"
    };

    slides.forEach((slide) => {
        const background = slide.querySelector(".slide-background");
        const filename = backgrounds[slide.dataset.slide];

        if (background && filename) {
            background.style.backgroundImage =
                `url("images/backgrounds/${filename}")`;
            background.style.backgroundSize = "cover";
            background.style.backgroundPosition = "center";
            background.style.backgroundRepeat = "no-repeat";
        }
    });

    // ==========================================
    // 2. SUPPORTING IMAGES  (images/)
    //    name in index.html  ->  file in images/
    //    "builtin:..." = picture stored at the bottom of this file
    // ==========================================

    const supportingImages = {
        // SLIDE 02 - GROUP MEMBERS
        "group-members-uterus-anatomy": "builtin:uterus",

        // SLIDE 03 - WHAT IS OVARIAN CANCER
        "healthy-ovary-versus-cancerous-ovary": "builtin:ovary",

        // SLIDE 08 - EARLY VS ADVANCED SYMPTOMS
        "early-stage-ovarian-cancer-medical-illustration":
            "ovarian_cancer_warning_signs_infographic.png",
        "advanced-stage-ovarian-cancer-medical-illustration":
            "abdominal_and_pelvic_metastasis_cutaway.png",

        // SLIDE 09 - STAGES OVERVIEW
        "figo-stages-one-to-four-overview":
            "figo_staging_stages_1_to_4_overview.png",

        // SLIDES 10-13 - INDIVIDUAL STAGES
        "stage-one-supporting-illustration":
            "figo_stage_1_crop.png",
        "stage-two-fallopian-tube-and-uterine-involvement":
            "fallopian_tube_and_uterine_tumor_anatomy.png",
        "stage-three-abdominal-peritoneal-spread":
            "stage_iii_vs_stage_iv_spread.jpg",
        "stage-four-distant-metastasis-diagram":
            "stage_iv_distant_metastasis_diagram.png",

        // SLIDE 14 - PROGRESSION
        "ovarian-cancer-five-step-progression-cycle":
            "five_step_cancer_progression_cycle.png",

        // SLIDE 18 - DIAGNOSTIC IMAGING
        "transvaginal-ultrasound-ovarian-mass":
            "transvaginal_ultrasound_left_ovarian_cyst.png",
        "pelvic-mri-complex-ovarian-mass":
            "pelvic_mri_complex_ovarian_mass.jpg",
        "pelvic-ct-large-pelvic-mass":
            "pelvic_ct_scan_large_mass.jpg"
    };

    document.querySelectorAll("[data-visual]").forEach((visual) => {
        if (visual.classList.contains("slide-background")) return;

        const entry = supportingImages[visual.dataset.visual];
        if (!entry) return;

        const source = entry.startsWith("builtin:")
            ? BUILT_IN_IMAGES[entry.slice(8)]
            : `images/${entry}`;

        // Only use the image if it really loads, so a missing file
        // never leaves an empty frame (the CSS hides the box instead).
        const probe = new Image();

        probe.onload = () => {
            visual.style.backgroundImage = `url("${source}")`;
            visual.style.backgroundSize = "contain";
            visual.style.backgroundPosition = "center";
            visual.style.backgroundRepeat = "no-repeat";
        };

        probe.onerror = () => {
            console.warn("Missing image for:", visual.dataset.visual,
                "-", entry);
        };

        probe.src = source;
    });

    // ==========================================
    // 3. SLIDE NAVIGATION
    // ==========================================

    function showSlide(index) {
        if (index < 0 || index >= slides.length) return;

        slides.forEach((slide, i) => {
            slide.classList.toggle("active", i === index);
            slide.setAttribute("aria-hidden", i === index ? "false" : "true");
        });

        currentSlide = index;
        updateCounter();
    }

    function updateCounter() {
        const counter = slides[currentSlide].querySelector(".slide-counter");

        if (counter) {
            const current = String(currentSlide + 1).padStart(2, "0");
            const total = String(slides.length).padStart(2, "0");
            counter.textContent = `${current} / ${total}`;
        }
    }

    function nextSlide() {
        if (currentSlide < slides.length - 1) showSlide(currentSlide + 1);
    }

    function previousSlide() {
        if (currentSlide > 0) showSlide(currentSlide - 1);
    }

    // Keyboard
    document.addEventListener("keydown", (event) => {
        switch (event.key) {
            case "ArrowRight":
            case "ArrowDown":
            case "PageDown":
            case " ":
                event.preventDefault();
                nextSlide();
                break;

            case "ArrowLeft":
            case "ArrowUp":
            case "PageUp":
                event.preventDefault();
                previousSlide();
                break;

            case "Home":
                showSlide(0);
                break;

            case "End":
                showSlide(slides.length - 1);
                break;
        }
    });

    // Touchscreen swipe
    presentation.addEventListener("touchstart", (event) => {
        touchStartX = event.changedTouches[0].screenX;
    }, { passive: true });

    presentation.addEventListener("touchend", (event) => {
        const difference = touchStartX - event.changedTouches[0].screenX;

        if (Math.abs(difference) > 50) {
            if (difference > 0) {
                nextSlide();
            } else {
                previousSlide();
            }
        }
    }, { passive: true });

    // Start
    showSlide(0);
});


/* =============================================================
   BUILT-IN PICTURES (slides 2 and 3) - DO NOT EDIT BELOW THIS LINE
   ============================================================= */

const BUILT_IN_IMAGES = {
    uterus: "data:image/png;base64,",
    ovary: "data:image/jpeg;base64,"
};